using System.ComponentModel;
using System.Net;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

// ── State ───────────────────────────────────────────────────────────────
var notes = new List<string>();

// ── Tools ───────────────────────────────────────────────────────────────
var searchTool = AIFunctionFactory.Create(SearchWebAsync,
    "search_web", "Search the web for information on a topic.");

var takeNoteTool = AIFunctionFactory.Create(
    ([Description("The note to save")] string note) =>
    {
        notes.Add(note);
        Console.WriteLine($"  📝 Note #{notes.Count} saved");
        return $"Note #{notes.Count} saved.";
    },
    "take_note", "Save a research note for later reference.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        Console.WriteLine("  📖 Reading notes...");
        return notes.Count == 0
            ? "No notes yet."
            : string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
    },
    "read_notes", "Read all saved research notes.");

// ── Chat client ─────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// ── Prompt ──────────────────────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔬 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly.

        Follow this strategy:
        1. Search the web with 3-5 varied queries to gather diverse perspectives.
        2. After each search, take a note summarising the key findings.
        3. Once you have enough material, read your notes and produce a clear,
           well-structured summary with the most important facts and insights.

        Be thorough but concise. Cite specifics when possible.
        """),
    new(ChatRole.User,
        $"Please research the following topic and provide a summary: {topic}")
};

var options = new ChatOptions
{
    Tools = [searchTool, takeNoteTool, readNotesTool]
};

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("\n════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("════════════════════════════════════════\n");
Console.WriteLine(response.Text);

// ── Web search helper ───────────────────────────────────────────────────
[Description("Search the web for information")]
static async Task<string> SearchWebAsync(
    [Description("The search query string")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");

    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";

    try
    {
        var html = await http.GetStringAsync(url);

        var snippets = new List<string>();
        const string marker = "class=\"result__snippet\"";
        var pos = 0;

        while (snippets.Count < 5)
        {
            pos = html.IndexOf(marker, pos, StringComparison.Ordinal);
            if (pos < 0) break;

            var start = html.IndexOf('>', pos) + 1;
            var end = html.IndexOf("</", start, StringComparison.Ordinal);
            if (start <= 0 || end <= start) { pos++; continue; }

            var raw = html[start..end];
            var text = WebUtility.HtmlDecode(
                Regex.Replace(raw, "<[^>]+>", "")).Trim();

            if (!string.IsNullOrWhiteSpace(text))
                snippets.Add(text);

            pos = end;
        }

        return snippets.Count > 0
            ? string.Join("\n\n", snippets.Select((s, i) => $"[{i + 1}] {s}"))
            : "No results found. Try different search terms.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

